CREATE OR REPLACE FUNCTION public.request_referral_payout(_amount_cents integer,_method text,_destination_hint text) RETURNS public.referral_payouts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE prof public.referral_profiles; prog public.referral_programs; available bigint; payout public.referral_payouts;
BEGIN
 SELECT * INTO prof FROM public.referral_profiles WHERE user_id=auth.uid() FOR UPDATE;
 IF prof.id IS NULL OR prof.status<>'active' THEN RAISE EXCEPTION 'Approved affiliate account required'; END IF;
 SELECT * INTO prog FROM public.referral_programs WHERE singleton;
 IF NOT prog.enabled OR prog.operational_verified_at IS NULL OR NOT prog.payout_provider_configured THEN RAISE EXCEPTION 'Payout processing is not active'; END IF;
 IF NOT(_method=ANY(prog.payout_methods)) OR length(trim(coalesce(_destination_hint,'')))<3 THEN RAISE EXCEPTION 'Valid payout method and details required'; END IF;
 SELECT coalesce(sum(commission_amount_cents-reversed_cents-settled_cents) FILTER(WHERE status IN('approved','paid') AND coalesce(payable_at,approved_at)<=now()),0)-coalesce(sum(greatest(settled_cents-(commission_amount_cents-reversed_cents),0)) FILTER(WHERE status NOT IN('approved','paid')),0) INTO available FROM public.referral_commissions WHERE referral_profile_id=prof.id AND currency='usd' AND coalesce(affiliate_environment,'live')='live';
 available:=available-coalesce((SELECT sum(amount_cents) FROM public.referral_payouts WHERE referral_profile_id=prof.id AND currency='usd' AND status IN('requested','under_review','approved','processing')),0);
 IF _amount_cents<=0 OR _amount_cents>available OR _amount_cents<prog.minimum_payout_cents THEN RAISE EXCEPTION 'Amount must meet the minimum and available balance'; END IF;
 INSERT INTO public.referral_payouts(referral_profile_id,user_id,amount_cents,method,destination_hint) VALUES(prof.id,auth.uid(),_amount_cents,_method,trim(_destination_hint)) RETURNING * INTO payout;
 UPDATE public.referral_profiles SET payout_method=_method,payout_destination_hint=trim(_destination_hint) WHERE id=prof.id;
 INSERT INTO public.referral_audit_logs(actor_id,actor_role,action,entity_type,entity_id,referral_profile_id,detail) VALUES(auth.uid(),'customer','payout_requested','referral_payout',payout.id,prof.id,'Payout requested');
 RETURN payout;
END $$;
REVOKE ALL ON FUNCTION public.request_referral_payout(integer,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_referral_payout(integer,text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.affiliate_dashboard_stats() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN SELECT id INTO pid FROM public.referral_profiles WHERE user_id=auth.uid(); IF pid IS NULL THEN RETURN '{}'::jsonb; END IF; RETURN (WITH m AS(SELECT coalesce(sum(greatest(commission_amount_cents-reversed_cents,0)) FILTER(WHERE status='pending'),0) pending,coalesce(sum(greatest(commission_amount_cents-reversed_cents-settled_cents,0)) FILTER(WHERE status='approved'),0) approved,coalesce(sum(settled_cents),0) paid,coalesce(sum(reversed_cents),0) reversed,coalesce(sum(commission_amount_cents-reversed_cents-settled_cents) FILTER(WHERE status IN('approved','paid') AND coalesce(payable_at,approved_at)<=now()),0)-coalesce(sum(greatest(settled_cents-(commission_amount_cents-reversed_cents),0)) FILTER(WHERE status NOT IN('approved','paid')),0) available FROM public.referral_commissions WHERE referral_profile_id=pid AND currency='usd' AND coalesce(affiliate_environment,'live')='live'),p AS(SELECT coalesce(sum(amount_cents),0) requested FROM public.referral_payouts WHERE referral_profile_id=pid AND status IN('requested','under_review','approved','processing') AND currency='usd') SELECT jsonb_build_object('clicks',(SELECT count(*) FROM public.referral_clicks WHERE referral_profile_id=pid),'signups',(SELECT count(*) FROM public.referral_attributions WHERE referral_profile_id=pid),'customers',(SELECT count(*) FROM public.referral_attributions WHERE referral_profile_id=pid AND converted_at IS NOT NULL),'active_customers',0,'pending_cents',m.pending,'approved_cents',m.approved,'paid_cents',m.paid,'reversed_cents',m.reversed,'requested_cents',p.requested,'available_cents',greatest(m.available-p.requested,0)) FROM m,p); END $$;
REVOKE ALL ON FUNCTION public.affiliate_dashboard_stats() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.affiliate_dashboard_stats() TO service_role;